<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class ReportController extends Controller {
 public function groups(Request $r){$p=$this->period($r);$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();return view('reports.groups',compact('p','groups'));}
 public function group(Request $r,$group){$p=$this->period($r);$g=DB::table('study_groups')->find($group);abort_if(!$g,404);$rows=$this->groupRows($p->id,$group);$subjects=DB::table('lesson_occurrences as l')->join('subjects as s','s.id','=','l.subject_id')->where('l.academic_period_id',$p->id)->where('l.study_group_id',$group)->select('s.id','s.name')->distinct()->orderBy('s.name')->get();return view('reports.group',compact('p','g','rows','subjects'));}
 public function student(Request $r,$student){$p=$this->period($r);$s=DB::table('students')->find($student);abort_if(!$s,404);$subjects=DB::table('lesson_occurrences as l')->join('subjects as sub','sub.id','=','l.subject_id')->where('l.academic_period_id',$p->id)->where('l.study_group_id',$s->current_group_id)->groupBy('sub.id','sub.name')->select('sub.id','sub.name')->orderBy('sub.name')->get();foreach($subjects as $sub){$sub->avg=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->where('gr.student_id',$s->id)->where('l.subject_id',$sub->id)->avg(DB::raw('CAST(gr.value AS REAL)'));$sub->missed=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->where('a.student_id',$s->id)->where('l.subject_id',$sub->id)->whereIn('a.status',['absent','sick','excused'])->count();$sub->result=DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$s->id,'subject_id'=>$sub->id])->value('value');}return view('reports.student',compact('p','s','subjects'));}
 public function csv(Request $r,$group){$p=$this->period($r);$g=DB::table('study_groups')->find($group);abort_if(!$g,404);$rows=$this->groupRows($p->id,$group);return response()->streamDownload(function()use($rows){$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['ФИО','Средний балл','Пропуски','Опоздания'],';');foreach($rows as $x)fputcsv($o,[$x->fio,$x->avg_grade!==null?number_format($x->avg_grade,2,',',''):'',$x->missed,$x->late],';');fclose($o);},'group-'.$g->name.'-'.$p->id.'.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
 private function groupRows($period,$group){$mq=DB::table('student_group_memberships as m')->join('students as s','s.id','=','m.student_id')->where('m.academic_period_id',$period)->where('m.study_group_id',$group)->where('m.status','active');$students=$mq->exists()?$mq->select('s.*')->orderBy('s.last_name')->get():DB::table('students')->where('current_group_id',$group)->where('status','active')->orderBy('last_name')->get();foreach($students as $s){$s->fio=trim("$s->last_name $s->first_name $s->middle_name");$s->avg_grade=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where('l.academic_period_id',$period)->where('gr.student_id',$s->id)->avg(DB::raw('CAST(gr.value AS REAL)'));$base=DB::table('attendance_records as a')->join('lesson_occurrences as l','l.id','=','a.lesson_occurrence_id')->where('l.academic_period_id',$period)->where('a.student_id',$s->id);$s->missed=(clone $base)->whereIn('a.status',['absent','sick','excused'])->count();$s->late=(clone $base)->where('a.status','late')->count();}return $students;}
 private function period(Request $r){$p=$r->attributes->get('academic_period');abort_if(!$p,404,'Учебный период не выбран');return $p;}
}
